package connector_test

// generated_test.go — unit coverage for connector.IsGenerated (ADR-021 §2 /
// TI-5): the "Code generated ... DO NOT EDIT" header heuristic that lets
// fathom tag generated files instead of silently counting them as
// hand-written code.

import (
	"strings"
	"testing"

	"github.com/geoffmilleraz/fathom/internal/connector"
)

func TestIsGenerated_PlainSourceIsNotGenerated(t *testing.T) {
	if connector.IsGenerated([]byte("package main\n\nfunc main() {}\n")) {
		t.Error("hand-written source misclassified as generated")
	}
}

func TestIsGenerated_Empty(t *testing.T) {
	if connector.IsGenerated(nil) {
		t.Error("empty content misclassified as generated")
	}
	if connector.IsGenerated([]byte{}) {
		t.Error("empty slice misclassified as generated")
	}
}

func TestIsGenerated_ProtocGenGo(t *testing.T) {
	src := "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage foo\n"
	if !connector.IsGenerated([]byte(src)) {
		t.Error("protoc-gen-go header not detected as generated")
	}
}

func TestIsGenerated_Mockgen(t *testing.T) {
	src := "// Code generated by MockGen. DO NOT EDIT.\npackage mocks\n"
	if !connector.IsGenerated([]byte(src)) {
		t.Error("MockGen header not detected as generated")
	}
}

func TestIsGenerated_Stringer(t *testing.T) {
	src := "// Code generated by \"stringer -type=Foo\"; DO NOT EDIT.\npackage foo\n"
	if !connector.IsGenerated([]byte(src)) {
		t.Error("stringer header not detected as generated")
	}
}

func TestIsGenerated_HashCommentStyle(t *testing.T) {
	// YAML/shell-style comment prefix — the regex matches the marker text,
	// not the comment syntax.
	src := "# Code generated by some-tool. DO NOT EDIT.\nkey: value\n"
	if !connector.IsGenerated([]byte(src)) {
		t.Error("hash-comment generated header not detected")
	}
}

func TestIsGenerated_BeyondScanWindow(t *testing.T) {
	// The marker must appear within the first few lines; deep in the file it
	// no longer counts (mirrors the Go convention, which requires it before
	// the first non-comment line).
	src := strings.Repeat("blank\n", 10) + "// Code generated. DO NOT EDIT.\n"
	if connector.IsGenerated([]byte(src)) {
		t.Error("marker beyond the scan window should not flip the classification")
	}
}
